function avSvgSeguro(svg){ return typeof svg==='string' && /^<svg[\s>]/.test(svg) && !/<script|\son\w+=|javascript:/i.test(svg) ? svg : ''; }
async function avCarregarRecursos(d){
  if(!AV_ICONES) AV_ICONES = await planoLerJson('plano-livro-icones', {});
  const keys = new Set();
  (d.figuras||[]).forEach(f => keys.add(f.f));
  if(d.esquema && d.esquema.fig) keys.add(d.esquema.fig);
  if(d.aprof){ if(d.aprof.fonte && d.aprof.fonte.img) keys.add(d.aprof.fonte.img); if(d.aprof.enem && d.aprof.enem.img) keys.add(d.aprof.enem.img); }
  if(d.leituraEnem && d.leituraEnem.img) keys.add(d.leituraEnem.img);
  if(d.saeseQ && d.saeseQ.img) keys.add(d.saeseQ.img);
  if(d.priorQ && d.priorQ.img) keys.add(d.priorQ.img);
  (d.enemOficial||[]).forEach(q => { if(q.imagem) keys.add(q.imagem); });
  if(d.denso) (d.denso.explica||[]).forEach(e => { if(e.img) keys.add(e.img); });
  await Promise.all([...keys].filter(k => !(k in AV_IMG)).map(async k => { AV_IMG[k] = await planoLerJson(`plano-livro-img:${k}`, null); }));
  // fotos/imagens dos slides criados pelo professor
  await Promise.all((d.extras||[]).filter(x => x && x.img && !(('ed-' + x.img) in AV_IMG)).map(async x => { AV_IMG['ed-' + x.img] = await planoLerJson(`plano-slides-ed-img:${x.img}`, null); }));
}
function avIc(nome, cor, extra){ const svg = avSvgSeguro((AV_ICONES||{})[nome]); return svg ? `<span class="av-ic" style="color:${cor};${extra||''}">${svg}</span>` : ''; }
function avCirc(nome, fundo, cor, tam){ return `<span class="av-circ" style="background:${fundo}; width:${tam}em; height:${tam}em;">${avIc(nome, cor, `font-size:${(tam*0.55).toFixed(2)}em;`)}</span>`; }
function avPassosEsquema(e){ return ({ comparar:2, quatro:4, tres:3, linha:(e.itens||[]).length, passos:(e.itens||[]).length, encolher:4, limite:3, figura:1 })[e.tipo] || 1; }
function avMontarSlides(d, opts){
  const estudo = !!(opts && opts.estudo);
  const leitura = (!estudo && opts && opts.leitura) || 0;
  const m = d.mapa && (d.mapa.ramos||[]).length ? d.mapa : null;
  const L = [{ t:'capa' }];
  if(d.priorFoco) L.push({ t:'prior-abre' });
  if(m) L.push({ t:'mapa-inicio' });
  L.push({ t:'retomada' });
  if(!estudo) L.push({ t:'nuvem' });
  L.push({ t:'aprender' });
  if(leitura) L.push({ t:'leitura', min: leitura, pos: L.length });
  let r = 0; const ramo = () => { if(m && r < m.ramos.length) L.push({ t:'caderno', k: r++ }); };
  ramo();
  (d.matematica||[]).forEach((mt, i) => { L.push({ t:'mat', i }); if(mt && mt.treino) L.push({ t:'mat-res', i }); });
  if(d.destaque) L.push({ t:'destaque' });
  (d.figuras||[]).forEach((f, i) => L.push({ t:'figura', i }));
  (d.videos||[]).forEach((v, i) => { if(v && v.id) L.push({ t:'video', i }); });
  if((d.figuras||[]).length) ramo();
  const dn = d.denso || null;
  const passos = (dn && dn.tabela && d.esquema && d.esquema.tipo==='comparar') ? 0 : avPassosEsquema(d.esquema);
  for(let k=0; k<passos; k++) L.push({ t:'esquema', k, passos });
  ramo();
  const ap = d.aprof || null;
  // conteúdo denso (explicação de verdade): substitui os slides curtos equivalentes do Aprofundamento
  const dEx = (dn && dn.explica) || [];
  if(dEx[0]) L.push({ t:'dn-ex', k:0 }); if(dEx[1]) L.push({ t:'dn-ex', k:1 });
  if(dn && dn.linha) L.push({ t:'dn-linha' });
  for(let k=2; k<dEx.length; k++) L.push({ t:'dn-ex', k });
  if(dn && (dn.conceitos||[]).length) L.push({ t:'dn-conc' });
  if(dn && dn.tabela) L.push({ t:'dn-tab' });
  if(ap){
    if(ap.contexto && !dEx.length) L.push({ t:'ap-contexto' });
    if((ap.conceitos||[]).length && !(dn && (dn.conceitos||[]).length)) L.push({ t:'ap-conceitos' });
    if(ap.fonte) L.push({ t:'ap-fonte' }, { t:'ap-fonte-res' });
  }
  if(dn && dn.causas) L.push({ t:'dn-causas' });
  if(dn && dn.autores) L.push({ t:'dn-autores' });
  if(dn && dn.caso) L.push({ t:'dn-caso' });
  if(dn && dn.objecao) L.push({ t:'dn-obj' });
  if(ap){
    if(ap.processo && !(dn && dn.causas)) L.push({ t:'ap-processo' });
    if(ap.interpretacoes && !(dn && (dn.autores || dn.objecao))) L.push({ t:'ap-interp' });
  }
  L.push({ t:'relampago' }, { t:'resposta' }, { t:'conceito' });
  while(m && r < m.ramos.length) ramo();
  if((d.vf||[]).length) L.push({ t:'vf' });
  if(d.leituraEnem || (ap && ap.enem)) L.push({ t:'ap-enem' }, { t:'ap-enem-res' });
  if(d.priorQ) L.push({ t:'prior-q' }, { t:'prior-q-res' });
  if(d.saeseQ && !(d.priorQ && d.priorQ.base===d.saeseQ.base)) L.push({ t:'saese-q' }, { t:'saese-q-res' });
  (d.enemOficial||[]).slice(0, 2).forEach((q, k) => L.push({ t:'enem-of', k }, { t:'enem-of-res', k }));
  if(ap && ap.sintese) L.push({ t:'ap-sintese' });
  if(d.proposta) L.push({ t:'proposta' }, { t:'proposta-res' });
  if(d.repertorio) L.push({ t:'repertorio' });
  if((d.conexoes||[]).length) L.push({ t:'conexoes' });
  if((d.trilhas||[]).length) L.push({ t:'trilha' });
  L.push({ t:'pratica' });
  if((!estudo && opts && opts.grupo) || (estudo && d.debate)) L.push({ t:'grupo' });
  if(m) L.push({ t:'mapa-final' });
  L.push({ t:'volte' });
  if(!estudo) L.push({ t:'termometro' });
  L.push({ t:'proxima' });
  return L;
}
