async function avDuvidaTirar(){ const av = aulaVivaState(); if(av.sess.duvidaTela) av.sess.duvidasOk = [...new Set([...(av.sess.duvidasOk||[]), av.sess.duvidaTela.id])]; av.sess.duvidaTela = null; render(); await aulaVivaSalvarSessao(); }
function avRoletaGirar(){
  const av = aulaVivaState(); const p = state.professor;
  const turma = (p.turmas||[]).find(t => t.id===av.sess.turmaId);
  const alunos = (turma && turma.students) || [];
  if(!alunos.length){ alert('Essa turma não tem alunos cadastrados.'); return; }
  let cand = alunos.filter(s => !(av.sess.sorteados||[]).includes(s.id));
  if(!cand.length){ av.sess.sorteados = []; cand = alunos; }
  av.painel = 'roleta'; av.girando = true; av.sess.sorteado = null; render();
  let ticks = 0;
  const tm = setInterval(() => {
    const el = document.getElementById('av-roleta-nome');
    if(el) el.textContent = cand[Math.floor(Math.random()*cand.length)].name;
    if(++ticks >= 18){
      clearInterval(tm);
      const pick = cand[Math.floor(Math.random()*cand.length)];
      av.girando = false;
      av.sess.sorteados = [...(av.sess.sorteados||[]), pick.id];
      av.sess.sorteado = { id: pick.id, nome: pick.name, fichas:false };
      render(); aulaVivaSalvarSessao();
    }
  }, 95);
}
async function avRoletaFicha(){
  const av = aulaVivaState(); const so = av.sess.sorteado; if(!so || so.fichas) return;
  so.fichas = true; render(); await aulaVivaSalvarSessao();
  try{ await awardFichas(av.sess.turmaId, so.id, 1, 'Participou na roleta da aula', 'roleta'); }catch(e){}
}
async function avPainelFechar(){
  const av = aulaVivaState();
  const tinha = av.painel==='roleta' && av.sess.sorteado;
  av.painel = null;
  if(tinha){ av.sess.sorteado = null; render(); await aulaVivaSalvarSessao(); } else render();
}
