function avPainelHtml(av){
  if(!av.painel) return '';
  let corpo = '';
  if(av.painel==='roleta'){
    const so = av.sess.sorteado;
    corpo = `<div style="font-size:1.1rem;color:#6B1F2E;font-weight:700;">🎡 Roleta da aula</div>
      <div id="av-roleta-nome" class="${av.girando?'':'av-pop'}" style="font-family:Cambria,Georgia,serif;font-size:clamp(2rem,6vw,4.4rem);font-weight:700;color:#1F4E79;margin:18px 0;min-height:1.3em;">${so ? '🎉 ' + esc(so.nome) : '…'}</div>
      ${av.girando ? '<div class="muted">Girando…</div>' : `<div style="display:flex;gap:8px;justify-content:center;flex-wrap:wrap;">
        <button class="btn btn-primary" data-action="av-roleta-ficha" ${so && so.fichas?'disabled':''}>${so && so.fichas?'✓ +1 ficha dada':'🏅 Participou: +1 ficha'}</button>
        <button class="btn btn-ghost" data-action="av-roleta-girar">🎡 Sortear outro</button>
        <button class="btn btn-ghost" data-action="av-painel-fechar">Fechar</button></div>
        <div class="muted" style="font-size:.8rem;margin-top:10px;">Quem já foi sorteado nesta aula não sai de novo até todos terem sido sorteados.</div>`}`;
  } else if(av.painel==='desafio'){
    corpo = `<div style="font-size:1.25rem;color:#6B1F2E;font-weight:700;margin-bottom:10px;">🏆 Desafio entre turmas — fichas da semana</div>
      ${avDesafioHtml(avDesafioCalcular(state.professor.turmas), av.sess.turmaId, true)}
      <button class="btn btn-ghost" data-action="av-painel-fechar" style="margin-top:12px;">Fechar</button>`;
  } else if(av.painel==='visto'){
    corpo = `${renderVistoPainel(av.sess.turmaId, av.n, true)}<button class="btn btn-ghost" data-action="av-painel-fechar" style="margin-top:10px;">Fechar</button>`;
  } else if(av.painel==='duvidas'){
    const ok = new Set(av.sess.duvidasOk||[]);
    const lista = Object.entries(av.duvidas||{}).filter(([id]) => !ok.has(id)).sort((a,b) => (a[1].at||0) - (b[1].at||0));
    corpo = `<div style="font-size:1.2rem;color:#6B1F2E;font-weight:700;">❓ Dúvidas da turma (anônimas)</div>
      <div class="muted" style="font-size:.82rem;margin-bottom:8px;">Só você vê esta lista. Escolha quais mostrar no telão.</div>
      <div style="max-height:55vh;overflow:auto;text-align:left;">${lista.length ? lista.map(([id, d]) => `<div data-av-duvida="${esc(id)}" style="border:1px solid #e6dcc8;border-radius:8px;padding:8px 10px;margin:6px 0;">
        <div style="font-size:1rem;">${esc(d.texto)}</div><div class="muted" style="font-size:.75rem;">${new Date(d.at||Date.now()).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</div>
        <div style="display:flex;gap:6px;margin-top:6px;flex-wrap:wrap;"><button class="btn btn-primary btn-sm" data-action="av-duvida-tela" data-id="${esc(id)}">📺 Mostrar no telão</button><button class="btn btn-ghost btn-sm" data-action="av-duvida-ok" data-id="${esc(id)}">✓ Respondida / esconder</button></div></div>`).join('')
        : '<p class="muted">Nenhuma dúvida nova. Os alunos mandam pelo botão “❓ Dúvida” no tablet.</p>'}</div>
      <button class="btn btn-ghost" data-action="av-painel-fechar" style="margin-top:10px;">Fechar</button>`;
  }
  return `<div class="av-over" data-av-painel="${av.painel}" data-av-fundo-fecha="1"><div class="av-over-card">${av.girando ? '' : '<button class="av-over-x" data-action="av-painel-fechar" title="Fechar" aria-label="Fechar">✕</button>'}${corpo}</div></div>`;
}
function avFaixaDuvidaHtml(sess, prof){
  if(!sess || !sess.duvidaTela) return '';
  return `<div class="av-faixa">❓ <b>Pergunta da turma:</b> ${esc(sess.duvidaTela.texto)}${prof ? ` <button class="btn btn-ghost btn-sm" data-action="av-duvida-tirar" style="background:#fff;margin-left:.6em;font-size:12px;">tirar da tela</button>` : ''}</div>`;
}
function avCtrlExtrasHtml(av){
  const sl = av.slides[av.sess.idx] || {};
  const ok = new Set(av.sess.duvidasOk||[]);
  const novas = Object.keys(av.duvidas||{}).filter(id => !ok.has(id)).length;
  return `${sl.t==='figura' && !(av.sess.toque && av.sess.toque.fig===sl.i) && AV_IMG[(av.d.figuras[sl.i]||{}).f] ? `<button class="btn btn-sm" style="background:#C9A227;color:#3b1018;" data-action="av-toque-abrir">📍 Toque na imagem</button>` : ''}
    <button class="btn btn-ghost btn-sm" data-action="av-roleta-girar" style="background:#fff;" title="Sorteia um aluno para responder">🎡 Sortear</button>
    <button class="btn btn-ghost btn-sm" data-action="av-desafio" style="background:#fff;" title="Ranking das turmas na semana">🏆 Desafio</button>
    ${av.d && av.d.mapa ? `<button class="btn btn-ghost btn-sm" data-action="av-visto-abrir" style="background:#fff;" title="Visto no mapa mental do caderno">📒 Visto</button>` : ''}
    <button class="btn btn-sm ${novas?'av-pisca':''}" data-action="av-duvidas" style="background:${novas?'#C9A227':'#fff'};color:#3b1018;" data-av-duvidas-n="${novas}">❓ Dúvidas${novas?` (${novas})`:''}</button>`;
}
function avChave(sess, extra){ return [sess.idx, sess.revelado, JSON.stringify(sess.perg||{}), sess.vf ? sess.vf.id+sess.vf.i+sess.vf.fase : '', sess.toque ? sess.toque.id+sess.toque.fase : '', sess.grupos ? sess.grupos.id : '', extra||''].join('|'); }
async function avAlunoSalvarInt(tipo, valor){
  const al = state.aluno; const s = al.aulaViva;
  if(!s || !al.matriculaStudentId) return;
  try{ await window.storage.set(`aula-viva-int:${s.id}:${tipo}:${al.matriculaStudentId}`, JSON.stringify(Object.assign({ nome: al.name, at: Date.now() }, valor)), true); }catch(e){}
}
function avMeu(){ const al = state.aluno; if(!al.avMeu || al.avMeu.sessId!==(al.aulaViva && al.aulaViva.id)) al.avMeu = { sessId: al.aulaViva && al.aulaViva.id, vfVisto:{}, duvidas:0 }; return al.avMeu; }
async function avAlunoNuvem(){
  const el = document.getElementById('av-nuvem-txt'); const w = (el ? el.value : '').trim().slice(0,30);
  if(!w) return;
  const m = avMeu(); m.nuvem = w; m.nuvemRascunho = ''; render();
  await avAlunoSalvarInt('nuvem', { w });
}
async function avAlunoTermo(v){ const m = avMeu(); m.termo = v; render(); await avAlunoSalvarInt('termo', { v }); }
async function avAlunoVf(v){
  const al = state.aluno; const s = al.aulaViva; const vf = s && s.vf;
  if(!vf || vf.fase!=='pergunta') return;
  const m = avMeu();
  if(!m.vf || m.vf.id!==vf.id) m.vf = { id: vf.id, r:{} };
  if(m.vf.r[vf.i]!==undefined) return;
  m.vf.r[vf.i] = v; render();
  await avAlunoSalvarInt('vf-'+vf.id, { r: m.vf.r });
}
async function avAlunoToque(x, y){
  const al = state.aluno; const tq = al.aulaViva && al.aulaViva.toque;
  if(!tq || tq.fase!=='aberto') return;
  const m = avMeu(); m.toque = { id: tq.id, x, y }; render();
  await avAlunoSalvarInt('toque-'+tq.id, { x, y });
}
async function avAlunoDuvidaEnviar(){
  const al = state.aluno; const s = al.aulaViva; if(!s) return;
  const el = document.getElementById('av-duvida-txt'); const t = (el ? el.value : '').trim().slice(0,200);
  if(!t) return;
  const m = avMeu();
  if(m.duvidas >= 3){ m.duvidaMsg = 'Você já mandou 3 dúvidas nesta aula. Se precisar, levante a mão. 🙂'; render(); return; }
  m.duvidas++; al.avDuvidaAberta = false; al.avDuvidaTxt = ''; m.duvidaMsg = '✔ Dúvida enviada! Só o professor vê, e sem o seu nome.';
  render();
  try{ await window.storage.set(`aula-viva-duvida:${s.id}:${cryptoId()}`, JSON.stringify({ texto: t, at: Date.now() }), true); }catch(e){}
  setTimeout(() => { if(m.duvidaMsg && m.duvidaMsg.startsWith('✔')){ m.duvidaMsg = ''; avRenderSeguro(); } }, 5000);
}
function avAlunoExtrasHtml(){
  const al = state.aluno; const s = al.aulaViva; const m = avMeu();
  const so = s.sorteado;
  const faixaSorteio = so ? `<div class="av-faixa" style="background:${so.id===al.matriculaStudentId?'#C9A227':'#1F4E79'};color:${so.id===al.matriculaStudentId?'#3b1018':'#fff'};top:0;bottom:auto;">🎡 ${so.id===al.matriculaStudentId ? '<b>É você!</b> O professor sorteou o seu nome. 🎉' : `Sorteado(a): <b>${esc(so.nome)}</b>`}</div>` : '';
  const modal = al.avDuvidaAberta ? `<div class="av-over"><div class="av-over-card" style="max-width:520px;text-align:left;">
      <div style="font-size:1.15rem;font-weight:700;color:#6B1F2E;">❓ Mandar uma dúvida</div>
      <div class="muted" style="font-size:.85rem;margin:4px 0 8px;">Anônimo: o professor vê a pergunta, mas não o seu nome.</div>
      <textarea id="av-duvida-txt" maxlength="200" rows="3" style="width:100%;font-size:1rem;" placeholder="Escreva aqui a sua dúvida">${esc(al.avDuvidaTxt||'')}</textarea>
      <div style="display:flex;gap:8px;margin-top:8px;"><button class="btn btn-primary" data-action="av-duvida-enviar">Enviar</button><button class="btn btn-ghost" data-action="av-duvida-cancelar">Cancelar</button></div></div></div>` : '';
  return { faixaSorteio, modal, msg: m.duvidaMsg ? `<span data-av-duvida-msg style="color:#F3E7C0;">${esc(m.duvidaMsg)}</span>` : '' };
}
function avTermoResumo(t){ if(!t || !t.total) return null; return { pctOk: Math.round(t.ok/t.total*100), pctNao: Math.round(t.nao/t.total*100), ...t }; }
function avTermoChipHtml(turmaId, n){
  const s = planoState(); const t = avTermoResumo(((s.termo||{})[turmaId]||{})[n]);
  if(!t) return '';
  const alerta = t.pctNao >= 30;
  return `<div data-termo-aula="${n}" style="margin-top:8px; font-size:.85rem; background:${alerta?'#fdecec':'#eef7f0'}; border-radius:8px; padding:6px 10px;">🌡️ <strong>Termômetro da turma:</strong> 😀 ${t.ok} · 😐 ${t.medio} · 😕 ${t.nao} <span class="muted">(${t.total} resposta(s))</span>${alerta ? ` — <strong style="color:#b3261e;">${t.pctNao}% não entenderam: vale retomar no início da próxima aula.</strong>` : ''}</div>`;
}
